from __future__ import annotations
from datetime import UTC, datetime
from sqlalchemy import DateTime, ForeignKey, Integer, String, Text
from sqlalchemy.orm import Mapped, mapped_column, relationship 
from database import Base

class User(Base):
    __tablename__ = "users"

    id:Mapped[int] = mapped_column(Integer, primary_key=True, index=True) # The id column is the primary key for the users table. It is an integer that is automatically generated by the database. The index=True argument creates an index on this column, which improves query performance when filtering by id.
    username:Mapped[str] = mapped_column(String(50), unique=True, nullable=False) # The username column is a string that is unique and cannot be null. This means that each user must have a unique username, and it cannot be left empty.
    email:Mapped[str] = mapped_column(String(120), unique=True, nullable=False) # The email column is a string that is unique and cannot be null. This means that each user must have a unique email address, and it cannot be left empty.
    image_file: Mapped[str | None] = mapped_column(String(200), nullable=True, default=None) # The image_file column is a string that can be null. This means that each user can have an optional profile image, and it can be left empty. The default value is None, which means that if no value is provided, it will be set to None.

    posts: Mapped[list[Post]] = relationship(back_populates="author") 
    
    # This is a relationship and this creates a one to many relationship here. 
    # This means that one user can have many posts. The back_populates argument specifies the 
    # name of the attribute on the Post class that will be used to access the related User object. 
    # It links to the author field on a post. This allows us to access the user who created a post 
    # by using post.author, and to access all posts created by a user by using user.posts.
    # We are referencing this post here before its defined so we have to use a string here. We are going to define the Post class below.
    # This is called forward reference. 

    @property
    def image_path(self) -> str: # if the user has uploaded a custom image then we're going to return that image from this /media/profile_pics/ directory. If the user has not uploaded a custom image then we're going to return the default image from the /static/profile_pics/ directory.
        if self.image_file:
            return f"/media/profile_pics/{self.image_file}"
        return "/static/profile_pics/default.jpg"

class Post(Base):
    __tablename__ = "posts"

    id: Mapped[int] = mapped_column(Integer, primary_key=True, index=True) # The id column is the primary key for the posts table. It is an integer that is automatically generated by the database. The index=True argument creates an index on this column, which improves query performance when filtering by id.
    title: Mapped[str] = mapped_column(String(100), nullable=False) # The title column is a string that cannot be null. This means that each post must have a title, and it cannot be left empty.
    content: Mapped[str] = mapped_column(Text, nullable=False) # The content column is a text field that cannot be null. This means that each post must have content, and it cannot be left empty.
    user_id: Mapped[int] = mapped_column(ForeignKey("users.id"), nullable=False, index=True) # The user_id column is a foreign key that references the id column in the users table. This establishes a relationship between the posts and users tables, allowing us to associate each post with a specific user. The index=True argument creates an index on this column, which improves query performance when filtering by user_id.
    date_posted: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=lambda: datetime.now(UTC),) # The lambda is a default here that just gets called at the creation of each post so that it sets that to the current datetime with the UTC timezone. This means that when a new post is created, the date_posted column will automatically be set to the current date and time in UTC. 

    author: Mapped[User] = relationship(back_populates="posts")
    # This is a many to one relationship. This means that many posts can be associated with one user. The back_populates argument specifies the name of the attribute on the User class that will be used to access the related Post objects. It links to the posts field on a user. This allows us to access the user who created a post by using post.author, and to access all posts created by a user by using user.posts.